import sys

def solve() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n, m = map(int, data[0].split())
    grid = data[1:1 + n]

    # Heights for each column (topmost '*' position)
    heights = []
    for col in range(m):
        h = 0
        for row in range(n):
            if grid[row][col] == '*':
                # row increases downward, so topmost is smallest row index
                # Height from the bottom (1‑based) = n - row
                h = n - row
                break
        heights.append(h)

    max_up = 0
    max_down = 0
    for i in range(1, m):
        diff = heights[i] - heights[i - 1]
        if diff > 0:
            max_up = max(max_up, diff)
        elif diff < 0:
            max_down = max(max_down, -diff)

    print(f"{max_up} {max_down}")

if __name__ == "__main__":
    solve()

