import sys

def solve() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n, m = map(int, data[0].split())
    grid = [list(row) for row in data[1:1 + n]]

    # Check each pair of black cells
    for r1 in range(n):
        for c1 in range(m):
            if grid[r1][c1] != '#':
                continue
            for r2 in range(n):
                for c2 in range(m):
                    if grid[r2][c2] != '#':
                        continue
                    # If both are black, then either they share a row or a column
                    # If not, they must come from the same operation, meaning the whole rectangle
                    # r1,c1 ; r1,c2 ; r2,c1 ; r2,c2 must all be black
                    if grid[r1][c2] == '.' or grid[r2][c1] == '.':
                        # Invalid: cannot have black at (r1,c1) and (r2,c2) without the corners
                        print("No")
                        return
    print("Yes")

if __name__ == "__main__":
    solve()
