import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    c = list(map(int, data[1:1 + n]))

    # compress consecutive duplicates
    a = [c[0]]
    for i in range(1, n):
        if c[i] != c[i - 1]:
            a.append(c[i])
    m = len(a)

    # dp[l][r] = min turns to make a[l..r] single color
    # initialize with 0 for l == r, and INF otherwise
    INF = 10 ** 9
    dp = [[0] * m for _ in range(m)]

    for length in range(2, m + 1):
        for l in range(m - length + 1):
            r = l + length - 1
            dp[l][r] = INF
            # if ends match, we can treat them as one component early
            if a[l] == a[r]:
                dp[l][r] = dp[l + 1][r - 1] + 1
            else:
                # recolor left end to match right, or right to match left
                dp[l][r] = min(dp[l + 1][r] + 1, dp[l][r - 1] + 1)
    print(dp[0][m - 1] if m > 1 else 0)

if __name__ == "__main__":
    solve()

