import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    max_index = 0
    # Find the index of the largest disk
    for i in range(n):
        if a[i] == n:
            max_index = i
            break

    left = max_index - 1
    right = max_index + 1
    current = n - 1  # we need to find disks n-1, n-2, ... , 1 in order

    while left >= 0 or right < n:
        if left >= 0 and a[left] == current:
            left -= 1
            current -= 1
        elif right < n and a[right] == current:
            right += 1
            current -= 1
        else:
            print("NO")
            return

    print("YES")

if __name__ == "__main__":
    solve()

