        acc = 0
        for j in range(m):
            left[i][j] = acc
            if grid[i][j] == 1:
                acc = 1
        acc = 0
        for j in range(m - 1, -1, -1):
            right[i][j] = acc
            if grid[i][j] == 1:
                acc = 1

    # Top to bottom
