import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    pairs = []
    idx = 1
    for _ in range(n):
        a = int(data[idx])
        b = int(data[idx + 1])
        pairs.append((a, b))
        idx += 2

    # Map: student_id -> (front, back)
    adj = {}
    indegree = {}
    zero_front = None

    for a, b in pairs:
        if a != 0:
            if a not in adj:
                adj[a] = [0, 0]
            adj[a][1] = b
        if b != 0:
            if b not in adj:
                adj[b] = [0, 0]
            adj[b][0] = a
        if a == 0:
            zero_front = b  # b is the first person in line
        if a != 0 and a not in indegree:
            indegree[a] = 0
        if b != 0:
            indegree[b] = indegree.get(b, 0) + 1

    # Find the person with indegree 0 among the second positions (starts the odd positions chain)
    second_chain_start = None
    for node in indegree:
        if indegree[node] == 0:
            second_chain_start = node
            break

    result = [0] * n
    # Fill even indices (0-based) with the first chain
    pos = 0
    cur = zero_front
    while cur != 0 and pos < n:
        result[pos] = cur
        pos += 2
        if cur in adj:
            cur = adj[cur][1]
        else:
            break

    # Fill odd indices with the second chain
    pos = 1
    cur = second_chain_start
    while cur != 0 and pos < n:
        result[pos] = cur
        pos += 2
        if cur in adj:
            cur = adj[cur][1]
        else:
            break

    print(' '.join(map(str, result)))

if __name__ == "__main__":
