def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    l = int(data[0])
    n = data[1]

    # Try to split as close to the middle as possible
    # but avoid leading zeros in either part.
    best = None

    # Try splitting after position i (0-indexed), where i is the last digit of the left part
    # left part length = i+1, right part length = l - i - 1
    # Both parts must be non-empty and without leading zeros.

    # Look for candidate splits near the middle to minimize sum length
    mid = l // 2

    # Check positions around the middle that give valid splits
    candidates = []
    # Try to the right of middle
    for offset in range(l):
        for direction in (-1, 1):
            pos = mid + direction * offset
            if 0 <= pos < l - 1:
                candidates.append(pos)
        if len(candidates) >= 4:  # We only need a few candidates
            break

    # Also add the immediate left and right of middle explicitly
    for pos in [mid - 1, mid, mid + 1]:
        if 0 <= pos < l - 1:
            candidates.append(pos)

    # Remove duplicates and keep valid splits
    candidates = list(set(candidates))
    candidates.sort()

    for i in candidates:
        if n[i + 1] == '0':
            # right part starts with zero -> invalid
            continue
        if i + 1 > 1 and n[0] == '0':
            # left part has leading zero
            continue
        left = int(n[:i + 1])
        right = int(n[i + 1:])
        s = left + right
        if best is None or s < best:
            best = s

    # If best is still None (shouldn't happen given problem guarantees),
    # fallback to trying all splits (but l up to 100000 so we must be careful)
    if best is None:
        # Try from middle outwards more systematically
        for delta in range(l):
            for pos in [mid + delta, mid - delta]:
