                        continue
                    if pos + 1 > 1 and n[0] == '0':
                        continue
                    left = int(n[:pos + 1])
                    right = int(n[pos + 1:])
                    s = left + right
                    if best is None or s < best:
                        best = s
            if best is not None:
                break

    print(best)


if __name__ == "__main__":
