import sys
from collections import deque

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n, m = map(int, data[0].split())
    table = data[1:1+n]

    # 0..n-1 : first set dishes
    # n..n+m-1 : second set dishes
    total = n + m
    graph = [[] for _ in range(total)]
    rev_graph = [[] for _ in range(total)]

    # Build implication graph from conditions
    for i in range(n):
        row = table[i]
        for j in range(m):
            ch = row[j]
            if ch == '>':
                # dish i > dish (n+j)  =>  (n+j) < i
                # i has higher number => edge from (n+j) to i
                graph[n + j].append(i)
                rev_graph[i].append(n + j)
            elif ch == '<':
                # dish i < dish (n+j) => edge from i to (n+j)
                graph[i].append(n + j)
                rev_graph[n + j].append(i)
            else:  # '='
                # equal numbers: need both directions
                graph[i].append(n + j)
                graph[n + j].append(i)
                rev_graph[i].append(n + j)
                rev_graph[n + j].append(i)

    # Kosaraju's algorithm for SCC
    visited = [False] * total
    order = []

    def dfs1(v):
        visited[v] = True
        for to in graph[v]:
            if not visited[to]:
                dfs1(to)
        order.append(v)

    for v in range(total):
        if not visited[v]:
            dfs1(v)

    comp = [-1] * total
    current_comp = 0

    def dfs2(v):
        comp[v] = current_comp
        for to in rev_graph[v]:
            if comp[to] == -1:
                dfs2(to)

    for v in reversed(order):
        if comp[v] == -1:
            dfs2(v)
            current_comp += 1

    # Build DAG of components
    comp_graph = [set() for _ in range(current_comp)]
    indeg = [0] * current_comp
    for v in range(total):
        for to in graph[v]:
            if comp[v] != comp[to]:
                if comp[to] not in comp_graph[comp[v]]:
                    comp_graph[comp[v]].add(comp[to])
                    indeg[comp[to]] += 1

    # Topological order of components using Kahn
    q = deque([i for i in range(current_comp) if indeg[i] == 0])
    topo = []
    while q:
        c = q.popleft()
        topo.append(c)
        for nxt in comp_graph[c]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                q.append(nxt)

    if len(topo) != current_comp:
        print("No")
        return

    # Assign ranks in reverse topological order
    rank = [1] * current_comp
    for c in reversed(topo):
        max_child = 0
        for nxt in comp_graph[c]:
            max_child = max(max_child, rank[nxt])
        rank[c] = max_child + 1

    # Check for contradictions: if a dish from first set and dish from second set
    # are in same SCC but required to be < or >, that's already handled by SCC detection.
    # Also check for equal constraints that are not in same SCC -> contradiction
    for i in range(n):
        row = table[i]
        for j in range(m):
            ch = row[j]
            if ch == '=':
                if comp[i] != comp[n + j]:
                    print("No")
                    return
            elif ch == '>':
                if rank[comp[i]] <= rank[comp[n + j]]:
                    print("No")
                    return
            else:  # '<'
                if rank[comp[i]] >= rank[comp[n + j]]:
                    print("No")
                    return

    # Build answer
    ans = [0] * total
    for i in range(total):
        ans[i] = rank[comp[i]]

    print("Yes")
    print(' '.join(map(str, ans[:n])))
    print(' '.join(map(str, ans[n:])))

if __name__ == "__main__":
    solve()

