def solve():
    n = int(input().strip())
    divisors = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
        i += 1

    fun_values = []
    for g in divisors:
        # fun = (n*(n+2)//g - n) // 2
        fun = (n * (n + 2) // g - n) // 2
        fun_values.append(fun)

    fun_values.sort()
    print(' '.join(map(str, fun_values)))

