def main():
    s = sys.stdin.readline().strip()
    vowels = set('IEAOUY')
    n = len(s)

    # Precompute harmonic numbers H and prefix sums P
    H = [0.0] * (n + 2)
    for k in range(1, n + 2):
        H[k] = H[k - 1] + 1.0 / k

    P = [0.0] * (n + 2)
    for k in range(1, n + 2):
        P[k] = P[k - 1] + H[k]

    total = 0.0
    for i in range(1, n + 1):
        if s[i - 1] in vowels:
            total += P[n] - P[i] - P[n - i]

    print(f"{total:.7f}")

