import sys

def cmp_key(s: str) -> str:
    # Custom comparison: for two strings x and y, compare x+y vs y+x
    # We can't directly use cmp_to_key because we need only a key function.
    # Instead, we'll implement a sort key that simulates pairwise comparison.
    # We'll use a class with rich comparison methods.
    class Key:
        __slots__ = ('s',)
        def __init__(self, s):
            self.s = s
        def __lt__(self, other):
            return self.s + other.s < other.s + self.s
    return Key(s)

def main():
