import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    s = data[1]

    half = n // 2
    left_sum = 0
    right_sum = 0
    left_q = 0
    right_q = 0

    for i, ch in enumerate(s):
        if ch == '?':
            if i < half:
                left_q += 1
            else:
                right_q += 1
        else:
            digit = ord(ch) - ord('0')
            if i < half:
                left_sum += digit
            else:
                right_sum += digit

    # The game is balanced if:
    # left_sum + (left_q * 9) // 2 == right_sum + (right_q * 9) // 2
    # and left_q and right_q are both even? Not exactly.
    # Known result: Bicarp wins iff
    # left_sum + (left_q // 2) * 9 == right_sum + (right_q // 2) * 9
    # because each player can mirror moves.

    if left_sum + (left_q // 2) * 9 == right_sum + (right_q // 2) * 9:
        print("Bicarp")
    else:
        print("Monocarp")

