def angle_between(v1, v2):
    """Return the angle in radians between vectors v1 and v2."""
    dot = v1[0]*v2[0] + v1[1]*v2[1]
    det = v1[0]*v2[1] - v1[1]*v2[0]
    return math.atan2(det, dot)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    points = []
    for _ in range(n):
        x = float(next(it))
        y = float(next(it))
        points.append((x, y))

    # Brute force over all pairs (i, j) as the central segment
    max_angle = 0.0
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            # vectors from segment (i, j) to other points
            left_angles = []
            right_angles = []
            dx_center = points[j][0] - points[i][0]
            dy_center = points[j][1] - points[i][1]
            for k in range(n):
