                dx = points[k][0] - points[i][0]
                dy = points[k][1] - points[i][1]
                ang = angle_between((dx_center, dy_center), (dx, dy))
                # ang > 0 means left side, < 0 means right side
                if ang > 0:
                    left_angles.append(ang)
                else:
                    right_angles.append(-ang)  # store as positive
