import sys

def solve() -> None:
    s = sys.stdin.readline().strip()
    t = sys.stdin.readline().strip()

    # Count frequencies of characters in s and t
    freq_s = [0] * 26
    freq_t = [0] * 26

    for ch in s:
        freq_s[ord(ch) - ord('a')] += 1
    for ch in t:
        freq_t[ord(ch) - ord('a')] += 1

    # Check if all characters needed are present in s
    for i in range(26):
        if freq_t[i] > freq_s[i]:
            print("need tree")
            return

    # Check if s already equals t
    if s == t:
        print("array")  # actually zero operations, but by problem logic "array" is fine
        return

    # Check for automaton (t is a subsequence of s)
    i = j = 0
    while i < len(s) and j < len(t):
        if s[i] == t[j]:
            j += 1
        i += 1
    is_subsequence = (j == len(t))

    # Check if lengths are equal -> then only swaps are needed
    if len(s) == len(t):
        # Must have same multiset of chars (already checked above)
        print("array")
        return

    # Here len(s) > len(t)
    if is_subsequence:
        print("automaton")
    else:
        # Need both removal and swaps
        print("both")

if __name__ == "__main__":
    solve()

