import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    T = int(data[1])
    a = list(map(int, data[2:2 + n]))

    total_candies = 0
    while True:
        round_sum = 0
        round_cnt = 0
        for price in a:
            if round_sum + price <= T:
                round_sum += price
                round_cnt += 1
        if round_cnt == 0:
            break
        full_rounds = T // round_sum
        total_candies += full_rounds * round_cnt
        T -= full_rounds * round_sum
        # now T < round_sum, we try to buy what we can in one more pass
        for price in a:
            if T >= price:
                T -= price
                total_candies += 1
            else:
                continue
        # after this pass, T is too small for any purchase in one full loop
        # break out if no purchase happened in the last pass
        if round_cnt == 0:
            break

    print(total_candies)

if __name__ == "__main__":
    solve()

