import sys

def solve() -> None:
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n = int(data[0].strip())
    s = data[1].strip()

    # Simulate decoding by reversing the encoding process
    res = []
    for i in range(n):
        # If current length is odd, take from left side (middle left), else from right side
        if i % 2 == n % 2:
            # Take from beginning
            res.append(s[i])
        else:
            # Take from end and reverse later
            res.append(s[i])

    # Build the original string by placing characters in correct order
    original = []
    for i in range(n - 1, -1, -1):
        if (n - 1 - i) % 2 == 0:
            original.append(res[i])
        else:
            original.insert(0, res[i])

    print(''.join(original))

if __name__ == "__main__":
    solve()
