import sys

def main():
    s = sys.stdin.readline()
    n = len(s)
    i = 0
    lexemes = []

    while i < n:
        # skip spaces
        while i < n and s[i] == ' ':
            i += 1
        if i >= n:
            break

        # start of a lexeme
        if s[i] == '"':
            # quoted lexeme
            i += 1
            start = i
            while i < n and s[i] != '"':
                i += 1
            # s[i] is now the closing quote
            lexemes.append(s[start:i])
            i += 1  # skip closing quote
        else:
            # unquoted lexeme
            start = i
            while i < n and s[i] != ' ':
                i += 1
            lexemes.append(s[start:i])

    # output each lexeme surrounded by <>
    for lex in lexemes:
        print(f"<{lex}>")

if __name__ == "__main__":
    main()

