import sys

MOD = 1_000_000_007

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    s = data[1].strip()
    w = data[2].strip()

    # Counters
    eq = 0          # s == w
    gt = 0          # s > w
    lt = 0          # s < w
    s_q = 0         # s ?, w digit
    w_q = 0         # s digit, w ?
    q_q = 0         # both ?

    for sc, wc in zip(s, w):
        if sc == '?' and wc == '?':
            q_q += 1
        elif sc == '?':
            s_q += 1
            if wc != '?':
                # digit comparison possibilities
                # s > w: sc > wc  => 9 - int(wc) choices
                # s < w: sc < wc  => int(wc) choices
                # s = w: 1 choice
                pass  # we'll handle in the formula later
        elif wc == '?':
            w_q += 1
            if sc != '?':
                # similar
                pass
        else:
            # both digits
            if sc > wc:
                gt += 1
            elif sc < wc:
                lt += 1
            else:
                eq += 1

    # Total ways without considering incomparability
    total_ways = pow(10, s_q + w_q + 2 * q_q, MOD)

    # We'll subtract comparable cases:
    # Comparable means (all positions s >= w) OR (all positions s <= w)
    # We count ways for s >= w and s <= w, subtract their intersection (s == w)

    # 1. Count ways for s >= w
    ways_ge = 1
    for sc, wc in zip(s, w):
        if sc == '?' and wc == '?':
            ways_ge = ways_ge * 55 % MOD  # (0..9) choose sc >= wc: sum_{d=0..9} (d+1) = 55
        elif sc == '?':
            # sc >= digit wc
            choices = 10 - int(wc)  # digits from wc to 9
            ways_ge = ways_ge * choices % MOD
        elif wc == '?':
            # digit sc >= wc
            choices = int(sc) + 1   # digits from 0 to sc
            ways_ge = ways_ge * choices % MOD
        else:
            if sc < wc:
                ways_ge = 0
                break
            # else sc >= wc, multiply by 1

    # 2. Count ways for s <= w
    ways_le = 1
    for sc, wc in zip(s, w):
