def solve() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n = int(data[0])
    board = [list(row.strip()) for row in data[1:]]

    pieces = []
    attack = [[False] * n for _ in range(n)]

    # Collect all piece positions and mark all cells that are attacked
    for i in range(n):
        for j in range(n):
            if board[i][j] == 'o':
                pieces.append((i, j))
            elif board[i][j] == 'x':
                attack[i][j] = True
            elif board[i][j] == '.':
                pass  # already False

    # All possible move vectors (dx, dy) in range [-(n-1), n-1]
    possible_moves = set()
    for dx in range(-(n-1), n):
        for dy in range(-(n-1), n):
            possible_moves.add((dx, dy))

    # Remove moves that would contradict an 'x' cell not being attacked
    for i in range(n):
        for j in range(n):
            if board[i][j] == '.':
                # This cell must NOT be attacked by any piece
                # So for every piece, the move that would hit this cell is invalid
                for pi, pj in pieces:
                    dx = i - pi
                    dy = j - pj
                    if (dx, dy) in possible_moves:
                        possible_moves.remove((dx, dy))

    # Now check that every 'x' cell is indeed attacked by at least one piece with a remaining move
    # Also ensure no piece attacks another piece's square unless that square is also 'o' (but pieces can't move onto other pieces anyway)
    for i in range(n):
        for j in range(n):
            if board[i][j] == 'x':
                attacked = False
                for pi, pj in pieces:
                    dx = i - pi
                    dy = j - pj
                    if (dx, dy) in possible_moves:
                        attacked = True
                        break
                if not attacked:
                    print("NO")
                    return

    # Additional check: no move should land on another piece unless that cell is also 'o' (which is impossible because pieces block)
    # Actually, the problem says: "using this move, the piece moves from (x,y) to (x+dx,y+dy). You can perform the move if the cell (x+dx,y+dy) is within the boundaries of the board and doesn't contain another piece."
    # So moves that would land on a piece are not allowed, but such moves don't affect whether a cell is attacked? Wait, the definition of "attacked" is: "whether some of the pieces on the field can move to that cell".
    # If a cell contains another piece, it cannot be moved onto, so it is NOT attacked. But in the input, cells with 'o' may or may not be attacked (they are ignored). So we don't need to worry about moves landing on pieces for attack purposes.
    # However, we must ensure that a move vector (dx,dy) is never used to move a piece onto another piece's square. But since pieces are never on the same square, we must forbid moves that, from any piece, land on another piece's square.
    # But if we forbid such moves, then those destination squares are not attacked (which matches the 'o' cells being unspecified). So we can just keep all moves that don't hit another piece.
    # Let's filter out moves that, from any piece, land on another piece.
    for pi, pj in pieces:
        for qi, qj in pieces:
            if (pi, pj) == (qi, qj):
                continue
            dx = qi - pi
            dy = qj - pj
            if (dx, dy) in possible_moves:
                possible_moves.remove((dx, dy))

    # Re-check attack condition after removing those moves
    for i in range(n):
        for j in range(n):
            if board[i][j] == 'x':
                attacked = False
                for pi, pj in pieces:
                    dx = i - pi
                    dy = j - pj
                    if (dx, dy) in possible_moves:
                        attacked = True
                        break
                if not attacked:
                    print("NO")
                    return

    # Build the output move board of size (2n-1) x (2n-1)
    size = 2 * n - 1
    out_board = [['.' for _ in range(size)] for _ in range(size)]
    center = n - 1  # index of center row/col
    out_board[center][center] = 'o'

    for dx, dy in possible_moves:
        x = center + dx
        y = center + dy
        if 0 <= x < size and 0 <= y < size:
            out_board[x][y] = 'x'

    print("YES")
    for row in out_board:
        print(''.join(row))

