import math

def read_ints():
    return list(map(int, sys.stdin.readline().split()))

def cross(a, b):
    return (a[1]*b[2] - a[2]*b[1],
            a[2]*b[0] - a[0]*b[2],
            a[0]*b[1] - a[1]*b[0])

def dot(a, b):
    return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]

def sub(a, b):
    return (a[0]-b[0], a[1]-b[1], a[2]-b[2])

def add(a, b):
    return (a[0]+b[0], a[1]+b[1], a[2]+b[2])

def length(v):
    return math.sqrt(v[0]*v[0] + v[1]*v[1] + v[2]*v[2])

def normalize(v):
    l = length(v)
    return (v[0]/l, v[1]/l, v[2]/l)

def scalar_mul(v, s):
    return (v[0]*s, v[1]*s, v[2]*s)

def point_in_polygon_3d(point, poly, normal, centroid):
    # Project polygon and point to 2D plane perpendicular to normal
    # Choose basis vectors u, v perpendicular to normal
    # Pick u as arbitrary vector not parallel to normal
    if abs(normal[0]) > abs(normal[1]) or abs(normal[0]) > abs(normal[2]):
        u = (-normal[1], normal[0], 0)
    else:
        u = (0, -normal[2], normal[1])
    u = normalize(u)
    v = cross(normal, u)
    v = normalize(v)

    # Project all points
    proj_poly = []
    for p in poly:
        vec = sub(p, centroid)
        proj_poly.append((dot(vec, u), dot(vec, v)))
    vec_pt = sub(point, centroid)
    proj_pt = (dot(vec_pt, u), dot(vec_pt, v))

    # Winding number in 2D
    wn = 0
    n = len(proj_poly)
    for i in range(n):
        j = (i+1) % n
        yi = proj_poly[i][1]
        yj = proj_poly[j][1]
        if yi <= proj_pt[1]:
            if yj > proj_pt[1]:
                # Edge going upward
                xi = proj_poly[i][0]
                xj = proj_poly[j][0]
                # Check if point is to the left of edge
                if (xj - xi) * (proj_pt[1] - yi) - (yj - yi) * (proj_pt[0] - xi) > 0:
                    wn += 1
        else:
            if yj <= proj_pt[1]:
                # Edge going downward
                xi = proj_poly[i][0]
                xj = proj_poly[j][0]
                if (xj - xi) * (proj_pt[1] - yi) - (yj - yi) * (proj_pt[0] - xi) < 0:
