import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    grid = [list(map(int, list(next(it)))) for _ in range(N)]

    # Transform coordinates: grid[r][c] (r=0 top, c=0 left) corresponds to cell at (c, r) with corners:
    # (c, N-1-r), (c+1, N-1-r), (c, N-r), (c+1, N-r) in lattice (x, y) where y from 0 bottom to N top? Wait, need to match.
    # Let's define lattice y increasing upward, but grid rows decreasing y.
    # Let's map cell (r, c) to corners in lattice (x, y) with x from 0..N, y from 0..N where y = N - r (top row r=0 -> y=N), and bottom row r=N-1 -> y=1.
    # Actually, corners: bottom-left of cell is (c, N-1-r), top-right is (c+1, N-r).
    # So corners: (c, N-1-r), (c+1, N-1-r), (c, N-r), (c+1, N-r).
    # Let's store for each cell its four corners as (x, y) tuples.
    corners_of_cell = [[[] for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            y_bottom = N - 1 - r
            y_top = y_bottom + 1
            x_left = c
            x_right = c + 1
            corners_of_cell[r][c] = [(x_left, y_bottom), (x_right, y_bottom), (x_left, y_top), (x_right, y_top)]

    # Brute force rectangle corners
    for x1 in range(N):
        for x2 in range(x1+1, N+1):
            for y1 in range(N):
                for y2 in range(y1+1, N+1):
                    # Rectangle corners
                    rect_corners = {(x1, y1), (x1, y2), (x2, y1), (x2, y2)}
                    ok = True
                    for r in range(N):
                        if not ok:
                            break
                        row = grid[r]
                        for c in range(N):
                            expected = 0
                            for corner in corners_of_cell[r][c]:
                                if corner in rect_corners:
                                    expected += 1
                            if expected != row[c]:
                                ok = False
                                break
                    if ok:
                        print("Yes")
                        return
    print("No")

if __name__ == "__main__":
    solve()

