def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    cats = [0] * (n + 1)
    for i in range(1, n + 1):
        cats[i] = int(next(it))

    graph = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(it))
        v = int(next(it))
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node: int, parent: int, consecutive: int) -> int:
        if cats[node]:
            consecutive += 1
            if consecutive > m:
                return 0
        else:
            consecutive = 0

        # leaf check: only parent as neighbor (except root)
        is_leaf = True
        cnt = 0
        for neigh in graph[node]:
            if neigh != parent:
                is_leaf = False
                cnt += dfs(neigh, node, consecutive)

        if is_leaf:
            return 1
        return cnt

    answer = dfs(1, -1, 0)
    print(answer)

if __name__ == "__main__":
    solve()

