import sys

def can_achieve(target, n, m, w, heights):
    # Use a difference array to efficiently apply range updates
    diff = [0] * (n + 1)
    operations = 0

    for i in range(n):
        if i > 0:
            diff[i] += diff[i - 1]

        current_height = heights[i] + diff[i]
        if current_height < target:
            needed = target - current_height
            operations += needed
            if operations > m:
                return False
            diff[i] += needed
            # Mark the end of the watering range
            if i + w < n:
                diff[i + w] -= needed

    return operations <= m

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, m, w = map(int, data[:3])
    heights = list(map(int, data[3:3 + n]))

    low = min(heights)
    high = 10**9 + 10**5 + 5  # Upper bound: max height + possible growth

    while low < high:
        mid = (low + high + 1) // 2
        if can_achieve(mid, n, m, w, heights):
            low = mid
        else:
            high = mid - 1

    print(low)

if __name__ == "__main__":
