import sys

def main():
    s = sys.stdin.readline().strip()
    t = sys.stdin.readline().strip()
    m = len(s)
    n = len(t)

    # can_left[i] = True if s is subsequence of t[0:i] (i chars)
    can_left = [False] * (n + 1)
    pos = 0
    for i in range(n):
        if pos < m and t[i] == s[pos]:
            pos += 1
        can_left[i + 1] = (pos == m)
    # Once full match, all further prefixes also contain s
    for i in range(1, n + 1):
        if can_left[i]:
            for j in range(i + 1, n + 1):
                can_left[j] = True
            break

    # can_right[i] = True if s is subsequence of t[i:] (suffix starting at i)
    can_right = [False] * (n + 1)
    pos = m - 1
    for i in range(n - 1, -1, -1):
        if pos >= 0 and t[i] == s[pos]:
            pos -= 1
        can_right[i] = (pos < 0)
    # Once full match, all earlier suffixes also contain s
    for i in range(n - 1, -1, -1):
        if can_right[i]:
            for j in range(i - 1, -1, -1):
                can_right[j] = True
            break

    # Count cuts: cut after i means left = t[0:i], right = t[i:]
    # i from 1 to n-1
    ans = 0
    for i in range(1, n):
        if can_left[i] and can_right[i]:
            ans += 1
    print(ans)

if __name__ == "__main__":
    main()

