import sys
import math
from collections import Counter

MOD = 1000000007

def factorize(x):
    factors = Counter()
    # Check small primes (up to sqrt(x))
    d = 2
    while d * d <= x:
        while x % d == 0:
            factors[d] += 1
            x //= d
        d += 1 if d == 2 else 2  # after 2, check only odd numbers
    if x > 1:
        factors[x] += 1
    return factors

def modinv(a, p):
    # Fermat's for prime MOD
    return pow(a, p-2, p)

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    n = int(input_data[0])
    arr = list(map(int, input_data[1:1+n]))

    # Combine prime factors from all numbers
    total_factors = Counter()
    for num in arr:
        fac = factorize(num)
        for p, exp in fac.items():
            total_factors[p] += exp

    # Precompute factorials and inverse factorials
    # We need up to n + max_exponent
    max_exp = max(total_factors.values()) if total_factors else 0
    max_n = n + max_exp + 5
    fact = [1] * (max_n + 1)
    inv_fact = [1] * (max_n + 1)
    for i in range(2, max_n + 1):
        fact[i] = fact[i-1] * i % MOD
    inv_fact[max_n] = modinv(fact[max_n], MOD)
    for i in range(max_n-1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

    def comb(a, b):
        if b < 0 or b > a:
            return 0
        return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

    result = 1
    for exp in total_factors.values():
        result = result * comb(exp + n - 1, n - 1) % MOD

    print(result % MOD)

if __name__ == "__main__":
    solve()

