import math

MOD = 10**9 + 7

def factorize(x, prime_counts):
    d = 2
    while d * d <= x:
        while x % d == 0:
            prime_counts[d] += 1
            x //= d
        d += 1 if d == 2 else 2
    if x > 1:
        prime_counts[x] += 1

def main():
    n_line = stdin.readline().strip()
    if not n_line:
        return
    n = int(n_line)
    arr = list(map(int, stdin.readline().split()))

    prime_counts = defaultdict(int)
    for num in arr:
        factorize(num, prime_counts)

    # Precompute factorials and inverse factorials up to n
    fact = [1] * (n + 1)
    inv_fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = fact[i-1] * i % MOD

    # Fermat's little theorem for inverse factorial
    def mod_pow(a, b, mod):
        res = 1
        while b:
            if b & 1:
                res = res * a % mod
            a = a * a % mod
            b >>= 1
        return res

    inv_fact[n] = mod_pow(fact[n], MOD-2, MOD)
    for i in range(n-1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

    def comb(N, K):
        if K > N or K < 0:
            return 0
        # N can be large, but K is small (n-1)
        # Use direct multiplication for safety
        if K > N - K:
            K = N - K
        num = 1
        den = 1
        for i in range(K):
            num = num * (N - i) % MOD
            den = den * (i + 1) % MOD
        return num * mod_pow(den, MOD-2, MOD) % MOD

    result = 1
    r = n - 1
    for k in prime_counts.values():
        N = k + r
        result = result * comb(N, r) % MOD

    print(result)

