    data = sys.stdin.read().strip()
    if not data:
        return
    n = int(data)
    # pattern: count of integers from 1 to n whose binary representation
    # has equal number of 0s and 1s (ignoring leading zeros).
    # Let's implement a direct digit DP.
    s = bin(n)[2:]
    length = len(s)

    # dp[pos][balance][tight] = count
    # balance = ones - zeros, but zeros count depends on pos and leading zeros.
    # We can map balance offset by length to avoid negative indices.
    # Max possible balance length = len(s), so size up to 2*len(s)+1
    offset = length  # so balance + offset in [0, 2*length]
    dp = [[[0, 0] for _ in range(2*length + 1)] for __ in range(length + 1)]
    dp[0][offset][1] = 1  # starting at pos 0, balance 0, tight=True

    for pos in range(length):
        max_digit = 1
        for tight in range(2):
            if tight:
                max_digit = int(s[pos])
            for balance in range(2*length + 1):
                cur = dp[pos][balance][tight]
                if cur == 0:
                    continue
                for dig in range(max_digit + 1):
                    ntight = 1 if (tight and dig == max_digit) else 0
                    # update balance: if we are still in leading zeros? 
                    # Actually, we count from most significant bit.
                    # Let's treat zero as decreasing balance, one as increasing.
                    # But before first 1, zeros are leading and shouldn't affect balance.
                    # We can simulate by having a flag 'started'.
                    # Simpler: we can adjust balance only if started, else balance remains 0.
                    # But we don't have 'started' state here. Let's incorporate it.
    # Re-do DP with (pos, balance, tight, started)
    # balance offset by length, size 2*length+1.
    dp2 = [[[[0, 0], [0, 0]] for _ in range(2*length + 1)] for __ in range(length + 1)]
    # dp2[pos][balance][started][tight]
    dp2[0][offset][0][1] = 1

    for pos in range(length):
        max_digit = 1
        for tight in range(2):
            if tight:
                max_digit = int(s[pos])
            for started in range(2):
                for balance in range(2*length + 1):
                    cur = dp2[pos][balance][started][tight]
                    if cur == 0:
                        continue
                    for dig in range(max_digit + 1):
                        ntight = 1 if (tight and dig == max_digit) else 0
                        if started == 0:
                            if dig == 0:
                                # still not started
                                nstarted = 0
                                nbalance = balance
                            else:
