import sys

sys.setrecursionlimit(10000)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    s = int(next(it)) - 1  # zero-index

    graph = [[] for _ in range(n)]
    rev_graph = [[] for _ in range(n)]

    for _ in range(m):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        graph[u].append(v)
        rev_graph[v].append(u)

    # Kosaraju's algorithm to find SCCs
    visited = [False] * n
    order = []

    def dfs1(u):
        visited[u] = True
        for v in graph[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(n):
        if not visited[i]:
            dfs1(i)

    comp = [-1] * n
    current_comp = 0

    def dfs2(u, c):
        comp[u] = c
        for v in rev_graph[u]:
            if comp[v] == -1:
                dfs2(v, c)

    for u in reversed(order):
        if comp[u] == -1:
            dfs2(u, current_comp)
            current_comp += 1

    num_scc = current_comp

    # Build condensation DAG
    in_deg = [0] * num_scc
    # For each edge u->v in original graph, if comp[u] != comp[v], it's an edge between SCCs
    for u in range(n):
        cu = comp[u]
        for v in graph[u]:
            cv = comp[v]
            if cu != cv:
                in_deg[cv] += 1

    # SCC containing capital
    capital_comp = comp[s]

    # Count SCCs with in-degree 0, excluding the capital's SCC
    ans = 0
    for i in range(num_scc):
        if in_deg[i] == 0 and i != capital_comp:
            ans += 1

    print(ans)

if __name__ == "__main__":
    solve()
