    m = int(next(it))
    s = int(next(it)) - 1  # zero-index

    g = [[] for _ in range(n)]
    rg = [[] for _ in range(n)]   # reversed graph

    for _ in range(m):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        g[u].append(v)
        rg[v].append(u)

