import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    H = int(data[0])
    W = int(data[1])
    K = int(data[2])
    grid = data[3:]

    # Count black cells for each row and column
    black_rows = [0] * H
    black_cols = [0] * W
    total_black = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                black_rows[i] += 1
                black_cols[j] += 1
                total_black += 1

    ans = 0
    # Enumerate all subsets of rows (2^H possibilities)
    for row_mask in range(1 << H):
        # Enumerate all subsets of columns (2^W possibilities)
        for col_mask in range(1 << W):
            # Count how many black squares are painted red
            painted_black = 0

            # Rows chosen in row_mask
            for r in range(H):
                if (row_mask >> r) & 1:
                    painted_black += black_rows[r]

            # Columns chosen in col_mask
            for c in range(W):
                if (col_mask >> c) & 1:
                    painted_black += black_cols[c]

            # Subtract double-counted black squares (intersection of chosen rows and columns)
            for r in range(H):
                if (row_mask >> r) & 1:
                    for c in range(W):
                        if (col_mask >> c) & 1 and grid[r][c] == '#':
                            painted_black -= 1

            remaining = total_black - painted_black
            if remaining == K:
                ans += 1

    print(ans)

if __name__ == "__main__":
    solve()
