            # Add back blacks that were removed twice (intersection of selected row and column)
            for r in range(H):
                if mask_rows >> r & 1:
                    for c in range(W):
                        if mask_cols >> c & 1:
                            if grid[r][c] == '#':
                                black_count += 1

            if black_count == K:
                ans += 1

    print(ans)


