import sys

sys.setrecursionlimit(300000)

def find(parent, x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x

def union(parent, rank, a, b):
    ra = find(parent, a)
    rb = find(parent, b)
    if ra == rb:
        return False
    if rank[ra] < rank[rb]:
        parent[ra] = rb
    elif rank[ra] > rank[rb]:
        parent[rb] = ra
    else:
        parent[rb] = ra
        rank[ra] += 1
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    edges = []
    for _ in range(m):
        x = int(next(it)) - 1
        y = int(next(it)) - 1
        w = int(next(it))
        edges.append((w, x, y))

    # Find vertex with minimum a[i]
    min_idx = 0
    for i in range(1, n):
        if a[i] < a[min_idx]:
            min_idx = i

    # Add edges from min_idx to all others with cost a[min_idx] + a[j]
    for j in range(n):
        if j != min_idx:
            edges.append((a[min_idx] + a[j], min_idx, j))

    # Sort all edges by weight
    edges.sort()

    parent = list(range(n))
    rank = [0] * n
    total_cost = 0
    edges_used = 0

    for w, u, v in edges:
        if union(parent, rank, u, v):
