            min_vertex = i

    # Add regular edges via cheapest vertex
    for i in range(n):
        if i != min_vertex:
            edges.append((a[min_vertex] + a[i], min_vertex, i))

    # Kruskal's algorithm
    edges.sort()

    parent = list(range(n))
    rank = [0] * n

