sys.setrecursionlimit(300000)

def solve():
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (n + 1)

    def dfs(v, parent):
        stack = [(v, parent)]
        vertices = []
        edges_count = 0
        while stack:
            cur, par = stack.pop()
            if visited[cur]:
                continue
            visited[cur] = True
            vertices.append(cur)
            for nb in adj[cur]:
                edges_count += 1
                if not visited[nb]:
                    stack.append((nb, cur))
        # Each edge was counted twice (once from each endpoint)
        edges_count //= 2
        return vertices, edges_count

    cycles = 0
    for i in range(1, n + 1):
        if not visited[i]:
            vertices, edges = dfs(i, -1)
            if len(vertices) >= 3 and edges == len(vertices):
                cycles += 1
    print(cycles)

if __name__ == "__main__":
    solve()

