def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    K = int(data[1])

    ans = 0.0

    for i in range(1, N + 1):
        score = i
        if score >= K:
            ans += 1.0 / N
        else:
            # need to double until >= K
            need_flips = 0
            while score < K:
                score *= 2
                need_flips += 1
            prob = (1 / N) * (0.5 ** need_flips)
            ans += prob

    print("{:.12f}".format(ans))

