import sys

def solve() -> None:
    s = sys.stdin.readline().strip()
    n = len(s)

    # Count distinct letters and question marks
    seen_letters = set()
    has_digit = False
    q_count = 0

    for ch in s:
        if 'A' <= ch <= 'J':
            seen_letters.add(ch)
        elif ch == '?':
            q_count += 1

    distinct_letters = len(seen_letters)

    # First character can't be '0' in final code
    # If first char is a letter, its digit cannot be 0
    # If first char is '?', it cannot be 0
    # If first char is a digit (1-9), it's fixed and fine

    # Total possibilities for letters: 10Pk = 10 * 9 * ... * (10 - k + 1)
    # But if the first character is a letter, then its digit cannot be 0
    # So we adjust: first letter has 9 choices (1-9), remaining (k-1) letters: 9P(k-1)

    if distinct_letters == 0:
        letters_factor = 1
    else:
        if 'A' <= s[0] <= 'J':
            # First char is a letter
            letters_factor = 9  # choices for first letter
            # Remaining distinct letters count
            remaining = distinct_letters - 1
            for i in range(remaining):
                letters_factor *= (9 - i)
        else:
            # First char is not a letter
            letters_factor = 10
            for i in range(1, distinct_letters):
                letters_factor *= (10 - i)

    # Now handle question marks
    # If the first char is '?', it cannot be 0 -> 9 choices, others 10 choices
    if q_count > 0:
        if s[0] == '?':
            q_factor = 9 * (10 ** (q_count - 1))
        else:
            q_factor = 10 ** q_count
    else:
        q_factor = 1

    result = letters_factor * q_factor
    print(result)

if __name__ == "__main__":
    solve()

