def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, k = map(int, data)
    ans = float('inf')
    # iterate over possible remainders r = x % k
    for r in range(k):
        # remainder must satisfy 0 <= r < k, and (n % (r+1) == 0) for integer division?
        # Actually: Let x = q * k + r, with 0 <= r < k.
        # Then x div k = q, x mod k = r.
        # Equation: q * r = n  => q = n // r, provided r > 0 and n % r == 0.
        if r == 0:
            continue
        if n % r == 0:
            q = n // r
            x = q * k + r
            if x > 0:
                ans = min(ans, x)
    # Also, r can be 0? If r = 0, then q * 0 = n => n must be 0, but n >= 1, so no.
    # But we also need to consider the case where r = k? No, remainder is < k.
    # Wait: the remainder is defined as 0 <= r < k, so r cannot be k.
    # But there is a known trick: iterate over divisors of n as q = n / r.
    # Alternatively, iterate over possible q (x div k) values.
    for q in range(1, n + 1):
        if q > n:
            break
        if n % q == 0:
            r = n // q
            if 0 < r < k:
                x = q * k + r
                if x > 0:
                    ans = min(ans, x)
    print(ans)

