def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    INFINITE = False
    total = 0

    # Precompute penalty for patterns that cause infinite touching
    for i in range(1, n):
        if a[i-1] == 1 and a[i] == 2:
            total += 3
        elif a[i-1] == 1 and a[i] == 3:
            total += 4
        elif a[i-1] == 2 and a[i] == 1:
            total += 3
        elif a[i-1] == 3 and a[i] == 1:
            total += 4
        elif a[i-1] == 2 and a[i] == 3:
            INFINITE = True
            break
        elif a[i-1] == 3 and a[i] == 2:
            INFINITE = True
            break

    # Check for the special case 1 3 2 where the extra point is overcounted
    for i in range(2, n):
        if a[i-2] == 3 and a[i-1] == 1 and a[i] == 2:
            total -= 1

    if INFINITE:
        print("Infinite")
    else:
        print("Finite")
        print(total)

if __name__ == "__main__":
    solve()
