import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    # If n > m, two numbers must be congruent mod m, so their difference is divisible by m.
    if n > m:
        print(0)
        return

    result = 1
    for i in range(n):
        for j in range(i + 1, n):
            result = (result * (abs(a[i] - a[j]) % m)) % m
            if result == 0:
                print(0)
                return
    print(result % m)

if __name__ == "__main__":
    solve()

