```python
import sys

def solve() -> None:
    s = sys.stdin.readline().strip()
    n = len(s)
    words = []
    start = 0
    # Split by commas and semicolons
    for i in range(n):
        if s[i] == ',' or s[i] == ';':
            words.append(s[start:i])
            start = i + 1
    # Don't forget the last word
    words.append(s[start:])

    numbers = []
    others = []

    for w in words:
        if w == "":
            others.append(w)
        else:
            # Check if it's a nonnegative integer without leading zeros
            is_number = True
            if w[0] == '0':
                # Only "0" itself is allowed
                is_number = (len(w) == 1)
            else:
                # All characters must be digits
                for ch in w:
                    if not ('0' <= ch <= '9'):
                        is_number = False
                        break
            if is_number:
                numbers.append(w)
            else:
                others.append(w)

    # Output
    if numbers:
        print('"' + ','.join(numbers) + '"')
    else:
        print('-')

    if others:
        print('"' + ','.join(others) + '"')
    else:
        print('-')

if __name__ == "__main__":
    solve()
