import sys

def is_integer_word(word):
    # empty word is not a nonnegative integer
    if not word:
        return False
    # check if all characters are digits
    if not word.isdigit():
        return False
    # check for leading zero: if length > 1 and first char is '0'
    if len(word) > 1 and word[0] == '0':
        return False
    return True

def main():
    s = sys.stdin.readline().strip()

    words = []
    current_word = []

    # split by ',' or ';'
    for ch in s:
        if ch == ',' or ch == ';':
            words.append(''.join(current_word))
            current_word = []
        else:
            current_word.append(ch)
    # add last word
    words.append(''.join(current_word))

    a_parts = []
    b_parts = []

    for w in words:
        if is_integer_word(w):
            a_parts.append(w)
        else:
            b_parts.append(w)

    # output
    if a_parts:
        print('"' + ','.join(a_parts) + '"')
    else:
        print('-')

    if b_parts:
        print('"' + ','.join(b_parts) + '"')
    else:
        print('-')

if __name__ == "__main__":
    main()
